CREATE TABLE IF NOT EXISTS pending_searches(episode_id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,user_id uuid REFERENCES users(id) ON DELETE SET NULL,api_key_id uuid REFERENCES api_keys(id) ON DELETE SET NULL,request jsonb NOT NULL,question text NOT NULL,resume_hash text NOT NULL,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),resumed_at timestamptz);
